def run(question, search_results, fetch_title, fetch_text):
    q = (question or '').strip()
    ql = q.lower()
    math_words = [
        'math', 'mathemat', 'calculate', 'solve', 'equation', 'algebra', 'geometry',
        'trigon', 'fraction', 'decimal', 'percentage', 'percent', 'probability',
        'statistics', 'statistic', 'integral', 'derivative', 'factor', 'prime',
        'mean', 'median', 'mode', 'sum', 'product', 'difference', 'ratio', 'proportion'
    ]
    allowed = any(w in ql for w in math_words) or any(ch.isdigit() for ch in q)

    snippets = []
    if isinstance(search_results, list):
        for r in search_results[:5]:
            if isinstance(r, dict):
                title = (r.get('title') or '').strip()
                content = (r.get('content') or '').strip()
                url = (r.get('url') or '').strip()
                bit = ' '.join(x for x in [title, content[:220], url] if x)
                if bit:
                    snippets.append(bit[:400])
    if isinstance(fetch_title, str) and fetch_title.strip():
        snippets.append(fetch_title.strip()[:200])
    if isinstance(fetch_text, str) and fetch_text.strip():
        t = ' '.join(fetch_text.split())
        if t:
            snippets.append(t[:600])

    facts = []
    seen = set()
    for s in snippets:
        s2 = s.strip()
        key = s2.lower()
        if s2 and key not in seen:
            seen.add(key)
            facts.append(s2)
        if len(facts) >= 6:
            break

    if not allowed:
        facts = []

    facts_text = '\n'.join(f'- {f}' for f in facts) if facts else 'No useful math facts extracted.'
    return {
        'allowed': allowed,
        'facts': facts,
        'facts_text': facts_text
    }
